package com.autumnharvestc.server.sync;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
class SyncRollbackTest extends SyncApplicationHttpFixture {
    ObjectNode rollback(JsonNode receipt){return json.createObjectNode().put("formatVersion",1).put("intentId",newIntent()).put("sourceId",receipt.path("sourceId").asText()).put("historyId",receipt.path("historyId").asText()).put("expectedAssetVersion",currentVersion()).put("expectedSourceRevision","1");}
    @Test void savedHistoryReopensAndCoreRollsBackAsANewAssetVersionWithoutRewindingBaseline() throws Exception {
        var candidate=checkToCandidate(createUrlSource("/fast"));var before=assets.get(users.findById(Long.parseLong(editor().id())).orElseThrow(),f.workspace(),f.project()).files().stream().map(file->file.path()+"\n"+file.content()).sorted().toList();
        var receipt=body(sourceRequest("POST","/applications",editor(),application(candidate)).andExpect(status().isOk()));
        try(var connection=java.sql.DriverManager.getConnection(DATABASE_URL,"sa","")){try(var statement=connection.prepareStatement("SELECT before_content,after_content,history_json FROM sync_history WHERE project_id=? AND id=?")){statement.setLong(1,Long.parseLong(f.project()));statement.setString(2,receipt.path("historyId").asText());try(var rows=statement.executeQuery()){assertThat(rows.next()).isTrue();assertThat(json.readTree(rows.getString(3)).path("id")).isEqualTo(receipt.path("historyId"));assertThat(rows.getString(1)).isNotEqualTo(rows.getString(2));}}}
        JsonNode undone;var settings=new java.util.LinkedHashMap<String,Object>();settings.put("spring.datasource.url",DATABASE_URL);settings.put("server.port",0);settings.put("apicc.server.allow-registration",true);settings.put("apicc.collaboration.runtime.enabled",true);settings.put("apicc.collaboration.runtime.base-url",node.info.path("url").asText());settings.put("apicc.collaboration.runtime.secret-file",node.info.path("secretFile").asText());settings.put("apicc.execution.materials.master-key-file",key.toString());
        try(var reopened=new org.springframework.boot.builder.SpringApplicationBuilder(com.autumnharvestc.server.ApiccServerApplication.class).run(settings.entrySet().stream().map(entry->"--"+entry.getKey()+"="+entry.getValue()).toArray(String[]::new))){int port=((org.springframework.boot.web.servlet.context.ServletWebServerApplicationContext)reopened).getWebServer().getPort();var response=java.net.http.HttpClient.newHttpClient().send(java.net.http.HttpRequest.newBuilder(java.net.URI.create("http://127.0.0.1:"+port+f.projectUrl()+"/sync/rollbacks")).header("Authorization","Bearer "+editor().token()).header("Content-Type","application/json").POST(java.net.http.HttpRequest.BodyPublishers.ofString(rollback(receipt).toString())).build(),java.net.http.HttpResponse.BodyHandlers.ofString());assertThat(response.statusCode()).isEqualTo(200);undone=json.readTree(response.body());}assertThat(undone.path("kind").asText()).isEqualTo("rollback");assertThat(currentVersion()).isEqualTo("4");assertThat(undone.path("afterStamp").path("baselineRevision").asText()).isEqualTo("1");assertThat(undone.path("afterStamp").path("mappingRevision").asText()).isEqualTo("1");assertThat(assets.get(users.findById(Long.parseLong(editor().id())).orElseThrow(),f.workspace(),f.project()).files().stream().map(file->file.path()+"\n"+file.content()).sorted().toList()).isEqualTo(before);
    }

    @Test void persistedHistoryHasARealCoreRollbackConsumerAndCommitArtifacts() throws Exception {
        var receipt=body(sourceRequest("POST","/applications",editor(),application(checkToCandidate(createUrlSource("/fast")))).andExpect(status().isOk()));var input=rollbackInput(receipt);assertThat(core.call("sync-rollback",input,System.currentTimeMillis()+10000,32000000).path("writes").size()).isGreaterThan(0);var wrapper=json.createObjectNode().put("kind","online-commit");wrapper.set("input",input);var artifacts=org.junit.jupiter.api.Assertions.assertDoesNotThrow(()->core.call("sync-rollback",wrapper,System.currentTimeMillis()+10000,32000000));assertThat(artifacts.path("before").path("text").asText()).isEqualTo(jdbc.queryForObject("SELECT after_content FROM sync_history WHERE project_id=? AND id=?",String.class,Long.parseLong(f.project()),receipt.path("historyId").asText()));
    }
    ObjectNode rollbackInput(JsonNode receipt) throws Exception {
        var entry=json.readTree(jdbc.queryForObject("SELECT history_json FROM sync_history WHERE project_id=? AND id=?",String.class,Long.parseLong(f.project()),receipt.path("historyId").asText()));var state=jdbc.queryForMap("SELECT mapping_json,baseline_json FROM sync_sources WHERE project_id=? AND id=?",Long.parseLong(f.project()),receipt.path("sourceId").asText());var input=json.createObjectNode();input.set("history",entry);input.set("currentStamp",entry.path("afterStamp"));var current=json.createArrayNode();assets.get(users.findById(Long.parseLong(editor().id())).orElseThrow(),f.workspace(),f.project()).files().forEach(file->current.addObject().put("path",file.path()).put("content",file.content()));input.set("currentFiles",current);input.set("beforeFiles",json.readTree(jdbc.queryForObject("SELECT before_content FROM sync_history WHERE project_id=? AND id=?",String.class,Long.parseLong(f.project()),receipt.path("historyId").asText())));input.set("afterFiles",json.readTree(jdbc.queryForObject("SELECT after_content FROM sync_history WHERE project_id=? AND id=?",String.class,Long.parseLong(f.project()),receipt.path("historyId").asText())));input.set("mapping",json.readTree(state.get("mapping_json").toString()));input.set("baselineFiles",json.readTree(state.get("baseline_json").toString()));input.set("otherSourceMappings",json.createArrayNode());input.set("budget",json.createObjectNode().put("maxCompareInputBytes",16777216).put("maxCompareOutputBytes",8388608));return input;
    }

    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"history-integrity","expected-source","edited-source","later-edit","content-reference","baseline-reference","other-source"})
    void rollbackUsesOnlyVerifiedHistoryAndCurrentSourceProjectOwnership(String variant) throws Exception {
        var source=createUrlSource("/fast");var receipt=body(sourceRequest("POST","/applications",editor(),application(checkToCandidate(source))).andExpect(status().isOk()));var request=rollback(receipt);
        switch(variant){case "history-integrity"->{var entry=(ObjectNode)json.readTree(jdbc.queryForObject("SELECT history_json FROM sync_history WHERE project_id=?",String.class,Long.parseLong(f.project())));entry.put("integritySha256","f".repeat(64));jdbc.update("UPDATE sync_history SET history_json=? WHERE project_id=?",entry.toString(),Long.parseLong(f.project()));}case "expected-source"->request.put("expectedSourceRevision","9");case "edited-source"->sourceRequest("PUT","/sources/"+source.path("id").asText(),f.owner(),sourceUpdateBody(source).put("expectedAssetVersion","3")).andExpect(status().isOk());case "later-edit"->editProjectWithCurrentVersion();case "content-reference"->jdbc.update("UPDATE sync_history SET before_content=REPLACE(before_content,'T9','T9 changed') WHERE project_id=?",Long.parseLong(f.project()));case "baseline-reference"->{var baseline=(com.fasterxml.jackson.databind.node.ArrayNode)json.readTree(jdbc.queryForObject("SELECT baseline_json FROM sync_sources WHERE project_id=? AND id=?",String.class,Long.parseLong(f.project()),source.path("id").asText()));((ObjectNode)baseline.get(0)).put("content",baseline.get(0).path("content").asText()+"\n# persisted content was changed\n");jdbc.update("UPDATE sync_sources SET baseline_json=? WHERE project_id=? AND id=?",baseline.toString(),Long.parseLong(f.project()),source.path("id").asText());}case "other-source"->{var other=sourceBody("url").put("url",node.info.path("origin").asText()+"/other");sourceRequest("POST","/sources",f.owner(),write(other).put("expectedAssetVersion","3")).andExpect(status().isCreated());var mapping=(ObjectNode)json.readTree(jdbc.queryForObject("SELECT mapping_json FROM sync_sources WHERE project_id=? AND id=?",String.class,Long.parseLong(f.project()),source.path("id").asText()));mapping.put("sourceId",other.path("id").asText()).put("namespace",other.path("id").asText());jdbc.update("UPDATE sync_sources SET mapping_json=? WHERE project_id=? AND id=?",mapping.toString(),Long.parseLong(f.project()),other.path("id").asText());}}
        String version=currentVersion();sourceRequest("POST","/rollbacks",editor(),request).andExpect(status().isConflict());assertThat(currentVersion()).isEqualTo(version);assertThat(applicationMutationCount(request.path("intentId").asText())).isZero();
    }
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"source","mapping","baseline","authority"})
    void rollbackRechecksTheFixedPlanAfterCoreWork(String change) throws Exception {
        var source=createUrlSource("/fast");var receipt=body(sourceRequest("POST","/applications",editor(),application(checkToCandidate(source))).andExpect(status().isOk()));var request=rollback(receipt);java.nio.file.Files.deleteIfExists(node.directory.resolve("resolve-held"));control("/hold-resolve");var pending=java.util.concurrent.CompletableFuture.supplyAsync(()->{try{return sourceRequest("POST","/rollbacks",editor(),request).andReturn().getResponse().getStatus();}catch(Exception e){throw new java.util.concurrent.CompletionException(e);}});
        try{awaitNode("resolve-held");switch(change){case "source"->sourceRequest("PUT","/sources/"+source.path("id").asText(),f.owner(),sourceUpdateBody(source).put("expectedAssetVersion","3")).andExpect(status().isOk());case "mapping"->jdbc.update("UPDATE sync_sources SET mapping_revision='9' WHERE project_id=?",Long.parseLong(f.project()));case "baseline"->jdbc.update("UPDATE sync_sources SET baseline_revision='9' WHERE project_id=?",Long.parseLong(f.project()));case "authority"->capabilities(null,java.util.Map.of("sync.manage","deny"));}}finally{control("/release-resolve");}assertThat(pending.get(10,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(409);assertThat(currentVersion()).isEqualTo("3");
    }
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"apply","rollback"})
    void unavailableClassifierCannotBypassCurrentScriptEditPermission(String kind) throws Exception {
        var source=createUrlSource("/fast");if(kind.equals("apply")){capabilities(null,java.util.Map.of("script.edit","deny"));var request=application(checkToCandidate(source));control("/fail-classify");sourceRequest("POST","/applications",editor(),request).andExpect(status().isForbidden());assertThat(currentVersion()).isEqualTo("2");}
        else {var receipt=body(sourceRequest("POST","/applications",editor(),application(checkToCandidate(source))).andExpect(status().isOk()));capabilities(null,java.util.Map.of("script.edit","deny"));control("/fail-classify");sourceRequest("POST","/rollbacks",editor(),rollback(receipt)).andExpect(status().isForbidden());assertThat(currentVersion()).isEqualTo("3");}
    }
    void control(String path) throws Exception{java.net.http.HttpClient.newHttpClient().send(java.net.http.HttpRequest.newBuilder(java.net.URI.create(node.info.path("origin").asText()+path)).GET().build(),java.net.http.HttpResponse.BodyHandlers.discarding());}

    @Test void anExpiredActiveOwnerCannotCommitEvenWhenCurrentHistoryIsStillRetained() throws Exception {
        var receipt=body(sourceRequest("POST","/applications",editor(),application(checkToCandidate(createUrlSource("/fast")))).andExpect(status().isOk()));var request=rollback(receipt);java.nio.file.Files.deleteIfExists(node.directory.resolve("resolve-held"));control("/hold-resolve");var pending=java.util.concurrent.CompletableFuture.supplyAsync(()->{try{return sourceRequest("POST","/rollbacks",editor(),request).andReturn().getResponse().getStatus();}catch(Exception e){throw new java.util.concurrent.CompletionException(e);}});
        try{awaitNode("resolve-held");var pins=(com.fasterxml.jackson.databind.node.ArrayNode)json.readTree(jdbc.queryForObject("SELECT active_owners_json FROM sync_history WHERE project_id=? AND id=?",String.class,Long.parseLong(f.project()),receipt.path("historyId").asText()));assertThat(pins.size()).isEqualTo(1);pins.forEach(pin->((ObjectNode)pin).put("expiresAtMs",0));jdbc.update("UPDATE sync_history SET active_owners_json=? WHERE project_id=? AND id=?",pins.toString(),Long.parseLong(f.project()),receipt.path("historyId").asText());}finally{control("/release-resolve");}assertThat(pending.get(10,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(409);assertThat(currentVersion()).isEqualTo("3");
    }
}
